# Anti-pattern data, part A: structure, names and links, ARIA.
# R(...) = regex detector, S(...) = CSS selector detector, X(...) = structural description.

def R(value, target='html', flags='i', unless=None, test=True):
    d = {'type': 'regex', 'target': target, 'value': value, 'flags': flags}
    if unless:
        d['unless'] = unless
    d['_test'] = test
    return d

def S(value):
    return {'type': 'selector', 'target': 'dom', 'value': value, '_test': False}

def X(value, target='dom'):
    return {'type': 'structural', 'target': target, 'value': value, '_test': False}

